using ShipmentTracker.Client.Models;
using ShipmentTracker.Client.Services;

namespace ShipmentTracker.Services;

/// <summary>
/// Server-side implementation using in-memory seed data.
/// Replace with EF Core or external API in production.
/// </summary>
public class ServerShipmentService : IShipmentService
{
    private static readonly List<Shipment> _shipments = new()
    {
        new() { Id = 1, TrackingNumber = "TRK-001", Origin = "New York, US", Destination = "London, UK", Status = ShipmentStatus.InTransit, EstimatedDelivery = DateTime.Today.AddDays(3), CustomerEmail = "alice@example.com" },
        new() { Id = 2, TrackingNumber = "TRK-002", Origin = "Shanghai, CN", Destination = "Los Angeles, US", Status = ShipmentStatus.PickedUp, EstimatedDelivery = DateTime.Today.AddDays(7), CustomerEmail = "bob@example.com" },
        new() { Id = 3, TrackingNumber = "TRK-003", Origin = "Berlin, DE", Destination = "Tokyo, JP", Status = ShipmentStatus.OutForDelivery, EstimatedDelivery = DateTime.Today.AddDays(1), CustomerEmail = "carol@example.com" },
        new() { Id = 4, TrackingNumber = "TRK-004", Origin = "Sydney, AU", Destination = "Dubai, AE", Status = ShipmentStatus.Pending, EstimatedDelivery = DateTime.Today.AddDays(10), CustomerEmail = "dave@example.com" },
        new() { Id = 5, TrackingNumber = "TRK-005", Origin = "São Paulo, BR", Destination = "Miami, US", Status = ShipmentStatus.Delivered, EstimatedDelivery = DateTime.Today.AddDays(-1), CustomerEmail = "eve@example.com" },
        new() { Id = 6, TrackingNumber = "TRK-006", Origin = "Mumbai, IN", Destination = "Singapore, SG", Status = ShipmentStatus.InTransit, EstimatedDelivery = DateTime.Today.AddDays(4), CustomerEmail = "frank@example.com" },
    };

    public Task<List<Shipment>> GetAllShipmentsAsync()
    {
        return Task.FromResult(_shipments.ToList());
    }

    public Task<Shipment?> GetByTrackingNumberAsync(string trackingNumber)
    {
        var shipment = _shipments.FirstOrDefault(s =>
            s.TrackingNumber.Equals(trackingNumber, StringComparison.OrdinalIgnoreCase));
        return Task.FromResult(shipment);
    }

    public Task UpdateStatusAsync(int id, ShipmentStatus status)
    {
        var shipment = _shipments.FirstOrDefault(s => s.Id == id);
        if (shipment is not null)
            shipment.Status = status;
        return Task.CompletedTask;
    }
}

using ShipmentTracker.Client.Models;
using ShipmentTracker.Client.Services;

namespace ShipmentTracker.Endpoints;

public static class ShipmentEndpoints
{
    public static void MapShipmentApi(this WebApplication app)
    {
        var group = app.MapGroup("api/shipments").RequireAuthorization();

        group.MapGet("", async (IShipmentService service) =>
            Results.Ok(await service.GetAllShipmentsAsync()));

        group.MapGet("track/{trackingNumber}", async (string trackingNumber, IShipmentService service) =>
        {
            var shipment = await service.GetByTrackingNumberAsync(trackingNumber);
            return shipment is not null ? Results.Ok(shipment) : Results.NotFound();
        });

        group.MapPut("{id}/status", async (int id, ShipmentStatus status, IShipmentService service) =>
        {
            await service.UpdateStatusAsync(id, status);
            return Results.NoContent();
        }).RequireAuthorization(policy => policy.RequireRole("Dispatcher"));
    }
}

